/**
 * src/offline/payloads.ts
 *
 * The 150 generated benchmark payloads, bundled with the app so the Quick test
 * runs with no server at all.
 *
 * assets/offline/payloads.json is generated by scripts/build-offline-payloads.ts
 * from the proxy's own output and checked by scripts/verify-offline-payloads.ts
 * (byte-identical to the proxy, sizes equal to the published payload_sizes.csv).
 * The 100 Spoonacular payloads are not in it.
 *
 * Each buffer becomes its own ArrayBuffer of exactly its length, the same shape
 * response.arrayBuffer() produces, so the codecs receive what they would have
 * received over the wire. Base64 decoding happens once, here, and is never
 * inside a measured bracket.
 */

import type { ComplexityTier, SerializationFormat } from '../../shared/contract';
import { SERIALIZATION_FORMATS } from '../../shared/contract';

export interface OfflineEntry {
  recipeId: number;
  tier: ComplexityTier;
  source: 'generated';
  /** UTF-8 length of the JSON encoding, the value tiers are assigned from. */
  byteLength: number;
  wireBytes: Record<SerializationFormat, number>;
}

interface OfflineFile {
  builtFromCommit: string;
  count: number;
  entries: (OfflineEntry & { base64: Record<SerializationFormat, string>; sha256: Record<SerializationFormat, string> })[];
}

export interface OfflineDataset {
  builtFromCommit: string;
  entries: OfflineEntry[];
  /** Raw bytes per payload and format. */
  bytes(recipeId: number, format: SerializationFormat): ArrayBuffer;
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const LOOKUP = new Uint8Array(128);
for (let i = 0; i < ALPHABET.length; i++) LOOKUP[ALPHABET.charCodeAt(i)] = i;

/** Standard base64 (with padding) to a standalone ArrayBuffer. */
export function base64ToArrayBuffer(b64: string): ArrayBuffer {
  const padding = b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0;
  const length = (b64.length / 4) * 3 - padding;
  const out = new Uint8Array(length);
  let o = 0;
  for (let i = 0; i < b64.length; i += 4) {
    const n =
      (LOOKUP[b64.charCodeAt(i)] << 18) |
      (LOOKUP[b64.charCodeAt(i + 1)] << 12) |
      (LOOKUP[b64.charCodeAt(i + 2)] << 6) |
      LOOKUP[b64.charCodeAt(i + 3)];
    if (o < length) out[o++] = (n >> 16) & 0xff;
    if (o < length) out[o++] = (n >> 8) & 0xff;
    if (o < length) out[o++] = n & 0xff;
  }
  return out.buffer;
}

let cached: OfflineDataset | null = null;

/**
 * Loads the bundle on first use. The require sits inside the function so the
 * 5.5 MB module is evaluated when a Quick test starts, not at app launch.
 */
export function loadOfflineDataset(): OfflineDataset {
  if (cached !== null) return cached;

  const file = require('../../assets/offline/payloads.json') as OfflineFile;

  const buffers = new Map<string, ArrayBuffer>();
  for (const e of file.entries) {
    for (const format of SERIALIZATION_FORMATS) {
      const buffer = base64ToArrayBuffer(e.base64[format]);
      if (buffer.byteLength !== e.wireBytes[format]) {
        throw new Error(
          `Offline payload ${e.recipeId} (${format}) is ${buffer.byteLength} bytes, expected ` +
            `${e.wireBytes[format]}. The bundled dataset is damaged; rebuild it.`
        );
      }
      buffers.set(`${e.recipeId}:${format}`, buffer);
    }
  }

  cached = {
    builtFromCommit: file.builtFromCommit,
    entries: file.entries.map(({ recipeId, tier, source, byteLength, wireBytes }) => ({
      recipeId,
      tier,
      source,
      byteLength,
      wireBytes,
    })),
    bytes(recipeId, format) {
      const b = buffers.get(`${recipeId}:${format}`);
      if (b === undefined) throw new Error(`No offline payload ${recipeId} (${format})`);
      return b;
    },
  };
  return cached;
}
